  Click(main,1076);Check(MapHash()==beijing,"Back restores prior city and view");Focus(main,C(main,1002));Key(0x27,alt:true);Check(MapHash()==canada,"Alt+Right restores the forward view");Click(main,1076);w=Search("Rome");Click(w,2306);Check(!IsWindowEnabled(C(main,1077)),"new destination clears stale forward navigation");
  Click(main,1082);w=Window("WorldMapExplorerUnifiedSearch");Check(Count(w)==2&&(int)SendMessage(C(w,2302),0x147,IntPtr.Zero,IntPtr.Zero)==4,"Saved opens a focused collection");Click(main,1024);Check(Text(w)=="Search and explore"&&(int)SendMessage(C(w,2302),0x147,IntPtr.Zero,IntPtr.Zero)==4&&Count(w)==2,"language switch updates open search and retains category");Shot(w,"04-saved-en");Close(w);
  w=Search("中国 北京");Check((int)SendMessage(C(w,2302),0x147,IntPtr.Zero,IntPtr.Zero)==0&&Count(w)>0&&Text(C(w,2305)).Contains("39.9075"),"new search resets category and accepts country plus Chinese city");Set(w,2301,"zzzznonexistentplace983451");Check(Count(w)==0&&!IsWindowEnabled(C(w,2306)),"no results disables opening and explains the empty state");Shot(w,"05-empty-search");Focus(w,C(w,2301));Key(0x1b);Check(!IsWindowVisible(w),"Escape closes search");Focus(main,C(main,1002));Key(0x46,ctrl:true);w=Window("WorldMapExplorerUnifiedSearch");Check(Focused()==C(w,2301),"Ctrl+F opens search ready for typing");Close(w);Click(main,1024);
  w=Search("Beagle");Category(w,3);Check(Count(w)>0,"journey search finds Beagle");Click(w,2306);Check(Visible(1048)&&Visible(1081)&&!Visible(1015),"opening a route activates its workspace");SendMessage(C(main,1081),0x405,(IntPtr)1,(IntPtr)5000);SendMessage(main,0x114,(IntPtr)4,C(main,1081));Check(Math.Abs((int)SendMessage(C(main,1081),0x400,IntPtr.Zero,IntPtr.Zero)-5000)<3,"route slider seeks by journey distance");Shot(main,"06-route-midpoint");
  w=Search("Apollo 11");Category(w,2);Check(Count(w)>0,"event search finds Apollo 11");Click(w,2306);var ev=Window("WorldMapExplorerEventSearch");Check(Visible(1015)&&!Visible(1048)&&Text(C(main,1047)).Contains("1969"),"event opens its year and history workspace");Close(ev);
  PickYear("1600");int middle=(int)SendMessage(C(main,1010),0x147,IntPtr.Zero,IntPtr.Zero);Click(main,1015);Check((int)SendMessage(C(main,1010),0x147,IntPtr.Zero,IntPtr.Zero)==middle,"history playback starts at the chosen year");Click(main,1015);int paused=(int)SendMessage(C(main,1010),0x147,IntPtr.Zero,IntPtr.Zero);SendMessage(main,0x113,(IntPtr)1017,IntPtr.Zero);Check((int)SendMessage(C(main,1010),0x147,IntPtr.Zero,IntPtr.Zero)==paused,"queued timer cannot advance a paused timeline");
  SendMessage(C(main,1080),0x405,(IntPtr)1,(IntPtr)5000);SendMessage(main,0x114,(IntPtr)4,C(main,1080));Check(Text(C(main,1047)).Contains("1601")&&!Text(C(main,1015)).Contains("暂停"),"history slider seeks and pauses playback");PickYear("1");Click(main,1078);Check(Text(C(main,1047)).Contains("前1"),"previous year crosses directly from CE 1 to BCE 1");Click(main,1079);Check(Text(C(main,1047)).StartsWith("公元1年  "),"next year skips nonexistent year zero");Shot(main,"07-history");
  Click(main,1075);Check(Visible(1008)&&Visible(1020),"Display exposes grid and animation settings");Focus(main,C(main,1008));SendMessage(C(main,1008),0x14f,(IntPtr)1,IntPtr.Zero);Key(0x1b);Check(Visible(1008)&&(int)SendMessage(C(main,1008),0x157,IntPtr.Zero,IntPtr.Zero)==0,"first Escape closes the combo without dismissing settings");Key(0x1b);Check(!Visible(1008),"second Escape closes settings");
  foreach(int width in new int[]{1024,800}){SetWindowPos(main,IntPtr.Zero,8,8,width,width==640?480:650,4);Thread.Sleep(300);Bounds("width "+width);Click(main,1074);Shot(main,"08-layers-"+width);Focus(main,C(main,1011));Key(0x1b);Click(main,1075);Shot(main,"09-display-"+width);Focus(main,C(main,1008));Key(0x1b);}
  SetWindowPos(main,IntPtr.Zero,8,8,640,480,4);R minimum;GetWindowRect(main,out minimum);Check(minimum.r-minimum.l>=800&&minimum.b-minimum.t>=600,"smallest window preserves usable 800 by 600 layout");
  SetWindowPos(main,IntPtr.Zero,12,12,1280,850,4);Thread.Sleep(250);Click(main,1070);Focus(main,C(main,1002));Key(0x7a);Check(!Visible(1002)&&!Visible(1070),"F11 expands to a map-only view");Shot(main,"10-fullscreen");Key(0x1b);Check(Visible(1002)&&Visible(1070),"Escape restores workspace controls");
  Stop();Start();Click(main,1082);w=Window("WorldMapExplorerUnifiedSearch");Check(Count(w)==2,"saved places persist across relaunch");Close(w);Click(main,1075);Click(main,1084);Check(Visible(1140),"fresh exploration remains available after restoring a view");R br;GetWindowRect(C(main,1076),out br);MapWindowPoints(IntPtr.Zero,main,ref br,2);int x=br.l+180,y=br.t+100;IntPtr point=(IntPtr)((y<<16)|(x&65535));SendMessage(main,0x201,(IntPtr)1,point);SendMessage(main,0x202,IntPtr.Zero,point);Thread.Sleep(300);Check(!Visible(1140)&&Visible(1083),"manual map selection updates start page and bookmark action");Shot(main,"11-map-selection");
 }catch(Exception e){Console.WriteLine("ERROR: "+e);failures++;}finally{Stop();}Console.WriteLine("RESULT checks="+checks+" failures="+failures);return failures==0?0:1;}
